  expect(Exit.isFailure(extractionResult)).toBe(true);
  expect(Exit.isFailure(duplicateResult)).toBe(true);
  expect(Exit.isFailure(cachedResult)).toBe(true);
} else {
  for (const result of [extractionResult, duplicateResult, cachedResult]) {
    expect(result._tag).toBe("Success");
    if (Exit.isSuccess(result)) expect(result.value).toBe(path + ".txt");
  }
}

